namespace Nexora.Domain.Catalog;
public sealed class Professional{private Professional(){}public Professional(Guid tenantId,string name,string?email,string?phone){Id=Guid.NewGuid();TenantId=tenantId;Update(name,email,phone,true);}public Guid Id{get;private set;}public Guid TenantId{get;private set;}public string Name{get;private set;}=string.Empty;public string?Email{get;private set;}public string?Phone{get;private set;}public bool IsActive{get;private set;}public ICollection<ProfessionalService>Services{get;}=[];public void Update(string name,string?email,string?phone,bool active){Name=name;Email=email;Phone=phone;IsActive=active;}}
public sealed class Service{private Service(){}public Service(Guid tenantId,string name,string?description,int durationMinutes,decimal price){Id=Guid.NewGuid();TenantId=tenantId;Update(name,description,durationMinutes,price,true);}public Guid Id{get;private set;}public Guid TenantId{get;private set;}public string Name{get;private set;}=string.Empty;public string?Description{get;private set;}public int DurationMinutes{get;private set;}public decimal Price{get;private set;}public bool IsActive{get;private set;}public ICollection<ProfessionalService>Professionals{get;}=[];public void Update(string name,string?description,int durationMinutes,decimal price,bool active){Name=name;Description=description;DurationMinutes=durationMinutes;Price=price;IsActive=active;}}
public sealed class ProfessionalService{private ProfessionalService(){}public ProfessionalService(Guid tenantId,Guid professionalId,Guid serviceId){TenantId=tenantId;ProfessionalId=professionalId;ServiceId=serviceId;}public Guid TenantId{get;private set;}public Guid ProfessionalId{get;private set;}public Professional Professional{get;private set;}=null!;public Guid ServiceId{get;private set;}public Service Service{get;private set;}=null!;}
